const express = require('express');
const speakeasy = require('speakeasy');
const jwt = require('jsonwebtoken');
const { User } = require('../models/user');

const app = express();
app.use(express.json());

app.post('/api/auth/2fa/verify', async (req, res) => {
  // Extract and verify pre-authentication temporary ticket
  const preAuthHeader = req.headers['x-preauth-token'];
  if (!preAuthHeader) {
    return res.status(401).json({ error: 'Pre-authentication session required' });
  }

  let sessionUser;
  try {
    sessionUser = jwt.verify(preAuthHeader, process.env.PREAUTH_JWT_SECRET);
  } catch {
    return res.status(401).json({ error: 'Invalid or expired pre-auth session' });
  }

  const { token } = req.body;
  if (!token) {
    return res.status(400).json({ error: 'TOTP token is required' });
  }

  // Bind lookup strictly to the authenticated user from the validated pre-auth ticket
  const user = await User.findById(sessionUser.userId);
  if (!user || !user.twoFactorSecret) {
    return res.status(404).json({ error: 'User or 2FA secret not configured' });
  }

  const verified = speakeasy.totp.verify({
    secret: user.twoFactorSecret,
    encoding: 'base32',
    token: token,
    window: 1
  });

  if (!verified) {
    return res.status(401).json({ error: 'Invalid 2FA code' });
  }

  const sessionToken = jwt.sign(
    { userId: user.id, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: '8h' }
  );

  res.json({ success: true, token: sessionToken });
});

app.listen(6001);
